    {
      "id": "2",
      "type": "IO",
      "text": "Returns -1 when out_cap is less than (len + 2) / 3 << 2.",
      "asserted_values": ["-1"],
      "confidence": 0.95,
      "io": {
        "when": "out_cap < (param_2 + 2) / 3 << 2",
