    {
      "id": "3",
      "type": "IO",
      "text": "Returns 0 when len is less than 3.",
      "asserted_values": ["0"],
      "confidence": 0.95,
      "io": {
        "when": "param_2 < 3",
        "returns": "0"
      }
    },
    {
      "id": "4",
      "type": "SIDE",
      "text": "Writes the encoded Base64 string to out.",
      "asserted_values": [],
      "confidence": 0.95
    },
    {
      "id": "5",
      "type": "CF",
      "text": "Handles len equal to 1, 2, and greater than 2 separately.",
      "asserted_values": [],
      "confidence": 0.95
    }
  ],
  "recovered_c": "uint64_t fn_07(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < (len + 2) / 3 << 2) {\n    return VERA_ERR;\n  }\n  if (len < 3) {\n    return 0;\n  }\n  size_t lVar7 = 0;\n  for (size_t uVar3 = 0; uVar3 < len; uVar3 += 3) {\n    uint uVar4 = (uint)in[uVar3] << 16 | (uint)in[uVar3 + 1] << 8 | (uint)in[uVar3 + 2];\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(uVar4 >> 18) & 0x3f];\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(uVar4 >> 12) & 0x3f];\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(uVar4 >> 6) & 0x3f];\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[uVar4 & 0x3f];\n  }\n  if (len % 3 == 1) {\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(in[len - 1] >> 2) & 0x3f];\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(in[len - 1] << 4) & 0x3f];\n    out[lVar7++] = '=';\n  } else if (len % 3 == 2) {\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(in[len - 2] >> 2) & 0x3f];\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[((in[len - 2] << 4) | (in[len - 1] >> 4)) & 0x3f];\n    out[lVar7++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(in[len - 1] << 2) & 0x3f];\n    out[lVar7++] = '=';\n  }\n  return lVar7;\n}"
}
